// Service worker for Zbroják: offline after the first visit.
// Version is a hash of index.html + data.js, generated by build_release.py.
const VERSION = 'a2d3de23e319';
const CACHE = 'zbrojak-' + VERSION;
const CORE = ['./', 'index.html', 'data.js', 'favicon.svg', 'favicon-32.png', 'apple-touch-icon.png', 'manifest.webmanifest', 'icon-192.png', 'icon-512.png'];
const IMAGES = ['img/q608.png', 'img/q609.png', 'img/q649.png', 'img/q650.png', 'img/q651.png', 'img/q652.png', 'img/q653.png', 'img/q654.png', 'img/q655.png', 'img/q656.png', 'img/q657.png', 'img/q658.png', 'img/q659.png', 'img/q660.png', 'img/q661.png', 'img/q662.png', 'img/q663.png', 'img/q664.png', 'img/q665.png', 'img/q666.png', 'img/q667.png', 'img/q668.png', 'img/q669.png', 'img/q670.png', 'img/q671.png', 'img/q672.png', 'img/q673.png', 'img/q674.png', 'img/q675.png', 'img/q676.png', 'img/q677.png', 'img/q678.png', 'img/q679.png', 'img/q680.png', 'img/q681.png', 'img/q682.png', 'img/q683.png', 'img/q684.png', 'img/q685.png', 'img/q686.png', 'img/q687.png', 'img/q688.png', 'img/q689.png', 'img/q690.png', 'img/q691.png', 'img/q692.png', 'img/q693.png', 'img/q694.png', 'img/q695.png', 'img/q696.png', 'img/q697.png', 'img/q698.png', 'img/q699.png', 'img/q700.png', 'img/q701.png', 'img/q702.png', 'img/q703.png', 'img/q704.png', 'img/q705.png', 'img/q706.png', 'img/q707.png', 'img/q708.png', 'img/q709.png', 'img/q710.png', 'img/q711.png', 'img/q712.png', 'img/q713.png', 'img/q714.png', 'img/q715.png', 'img/q716.png', 'img/q717.png'];
const CDN = ['https://cdnjs.cloudflare.com/ajax/libs/lz-string/1.5.0/lz-string.min.js'];
const abs = p => new URL(p, self.registration.scope).href;

self.addEventListener('install', e => {
  e.waitUntil((async () => {
    const c = await caches.open(CACHE);
    await c.addAll(CORE.map(abs));
    // images and the CDN script: best effort, a missing one must not block the install
    await Promise.allSettled([...IMAGES.map(abs), ...CDN].map(u => c.add(u).catch(() => null)));
    await self.skipWaiting();
  })());
});

self.addEventListener('activate', e => {
  e.waitUntil((async () => {
    for (const k of await caches.keys()) if (k !== CACHE) await caches.delete(k);
    await self.clients.claim();
  })());
});

self.addEventListener('fetch', e => {
  const req = e.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.hostname.endsWith('googleapis.com')) return;      // Firestore sync goes straight to the network
  const isPage = req.mode === 'navigate' || url.pathname.endsWith('/index.html') || url.pathname.endsWith('/data.js') || url.pathname.endsWith('/');
  if (isPage) {
    // network first: a new version is picked up as soon as there is a connection
    e.respondWith((async () => {
      try {
        const r = await fetch(req);
        if (r && r.ok) { const c = await caches.open(CACHE); c.put(req, r.clone()); }
        return r;
      } catch (err) {
        const c = await caches.open(CACHE);
        return (await c.match(req)) || (await c.match(abs(req.mode === 'navigate' ? 'index.html' : url.pathname.split('/').pop()))) || Response.error();
      }
    })());
    return;
  }
  // everything else (images, icons, CDN): cache first, then network
  e.respondWith((async () => {
    const c = await caches.open(CACHE);
    const hit = await c.match(req, { ignoreSearch: true });
    if (hit) return hit;
    try { const r = await fetch(req); if (r && (r.ok || r.type === 'opaque')) c.put(req, r.clone()); return r; }
    catch (err) { return Response.error(); }
  })());
});
